import pathlib
raw=pathlib.Path('weoapr2025all.xls').read_bytes()
text=raw.decode('utf-16')
lines=text.splitlines()
headers=lines[0].split('\t')
# map year to index
year_cols={int(h):i for i,h in enumerate(headers) if h.isdigit()}
# get Georgia rows
rows={}
for line in lines[1:]:
    parts=line.split('\t')
    if len(parts)<10:
        continue
    if parts[0]=='915' and parts[2] in ('NGDP_R','NGDP_RPCH'):
        rows[parts[2]]=parts
# extract 2000-2027
for code in ('NGDP_R','NGDP_RPCH'):
    parts=rows[code]
    vals={}
    for year in range(2000,2028):
        idx=year_cols[year]
        val=parts[idx] if idx < len(parts) else ''
        vals[year]=val
    print(code, list(vals.items())[:3], list(vals.items())[-3:])
PY"}

